s=s.replace('       def-axiom-of-choice]', '       def-axiom-of-choice, def-the-node-order-and-n-i-exponents-for-fock-space,\n       def-contravariant-form-on-an-integrable-quantum-highest-weight-module,\n       thm-the-fock-space-node-formulas-satisfy-the-quantum-affine-relations]')
